ing-left:12px;border-left:1px solid #24303c}.token-facts>strong{font-size:23px}.token-facts p{font-size:10px;color:#7c879b;margin:12px 0 18px}.token-facts .outline{font-size:8px;padding:10px}.oc-section{margin-top:66px;border:1px solid var(--line);background:#081219}.oc-title{display:flex;align-items:center;padding:12px 18px;gap:10px;font-size:10px;color:#6e8a9b;border-bottom:1px solid #16323d}.oc-title b{font-weight:normal;color:var(--cyan)}.oc-title>i{background:#777}.oc-title>i.online{background:#60ff00}.oc-title button{margin-left:auto;background:none;border:0;font-size:9px;color:var(--cyan)}.oc-metrics{display:grid;grid-template-columns:repeat(4,1fr);padding:20px}.oc-metrics>div{border-right:1px solid #15303a;padding-left:20px}.oc-metrics>div:first-child{padding-left:0}.oc-metrics>div:last-child{border:0}.oc-metrics span{display:block;font-size:8px;color:#678696;letter-spacing:.5px}.oc-metrics strong{display:block;font-size:16px;color:#bfe5f1;font-weight:normal;margin-top:7px}footer{padding:36px 0 28px;display:flex;align-items:center;gap:26px}.brand-text{font:700 15px 'Neon Orbit',sans-serif}footer p{color:#526679;font-size:9px;line-height:1.9}footer button{margin-left:auto;font-size:9px}.modal-backdrop{position:fixed;inset:0;background:#03050cdc;display:flex;align-items:center;justify-content:center;z-index:20}.modal{width:440px;max-width:calc(100% - 40px);padding:30px;box-shadow:0 0 70px #00f0f50c}.modal h2{font-size:21px;margin:10px 0 20px}.modal-close{position:absolute;right:12px;top:7px;background:none;border:0;color:#a3b7c7;font-size:25px}.modal p{color:#8c99b0;font-size:12px;margin:12px 0}.wallet-option{display:flex;align-items:center;gap:14px;width:100%;border:1px solid var(--line);background:#0a1b22;padding:16px;color:var(--cyan);text-align:left}.wallet-option b{display:block;color:#eef5ff;font-size:12px}.wallet-option small{font-size:9px;color:#6d93a4}.wallet-icon{font-size:24px;color:var(--cyan)}.modal-note{border-left:2px solid var(--cyan);padding-l