{path=[=[/home/ochd_apps/defi-yield/main.js]=],text=[=[(function(){'use strict';
var $=function(id){return document.getElementById(id);},hasOC=typeof window.OC==='object',days=180,filter='all',search='',connected=false,balance=10000,receipts=0,toastTimer,previousFocus;
var pools=[{id:'eth-usdc',pair:'ETH / USDC',type:'volatile',kind:'',icons:['Ξ','$'],apy:124.6,tvl:'$482.6M',volume:'$24.8M',fee:'0.30%'},{id:'usdc-usdt',pair:'USDC / USDT',type:'stable',kind:'stable',icons:['$','₮'],apy:18.4,tvl:'$728.1M',volume:'$86.2M',fee:'0.01%'},{id:'wbtc-eth',pair:'WBTC / ETH',type:'volatile',kind:'bitcoin',icons:['₿','Ξ'],apy:86.2,tvl:'$316.4M',volume:'$12.6M',fee:'0.30%'},{id:'neon-usdc',pair:'NEON / USDC',type:'volatile',kind:'neon',icons:['N','$'],apy:245.8,tvl:'$96.5M',volume:'$8.3M',fee:'0.30%'},{id:'dai-usdc',pair:'DAI / USDC',type:'stable',kind:'stable',icons:['◈','$'],apy:12.8,tvl:'$205.9M',volume:'$19.4M',fee:'0.05%'},{id:'eth-neon',pair:'ETH / NEON',type:'volatile',kind:'neon',icons:['Ξ','N'],apy:198.5,tvl:'$118.2M',volume:'$7.1M',fee:'0.30%'}],favorites={};
function money(n,places){return Number(n).toLocaleString('en-US',{minimumFractionDigits:places||0,maximumFractionDigits:places||0});}
function notify(text,failed){clearTimeout(toastTimer);$('toast').textContent=text;$('toast').className='toast'+(failed?' failure':'');$('toast').hidden=false;toastTimer=setTimeout(function(){$('toast').hidden=true;},6500);}
function emit(name,args){if(hasOC)return window.OC.emit(name,args||{});return new Promise(function(resolve,reject){setTimeout(function(){if(name==='demo_deposit'){if(!connected||args.amount>balance){reject({message:'Insufficient demo balance'});return;}balance-=args.amount;}if(name==='demo_connect')connected=true;if(name==='demo_disconnect')connected=false;receipts++;syncWallet();resolve({ok:true,message:'Browser preview receipt · no OC computer connected'});},180);});}
function syncWallet(){$('wallet-button').innerHTML=connected?'DEMO CONNECTED <span>●</span>':'CONNECT WALLET <span>↗</span>';$('calculator-wallet').textContent=connected?'EXPLORE LIQUIDITY POOLS →':'CONNECT WALLET TO START';$('demo-balance').textContent=money(balance,2)+' USDC';$('oc-receipts').textContent=String(receipts);}
function calculate(){var raw=$('amount').value.replace(/,/g,'').trim(),amount=Number(raw),apy=Number($('rate').value);if(!raw||!isFinite(amount)||amount<0||amount>1000000000){$('calc-error').textContent='Enter a deposit between 0 and 1,000,000,000 USDC.';return;}$('calc-error').textContent='';var earnings=amount*(Math.pow(1+apy/100,days/365)-1);$('rate-label').textContent=apy.toFixed(1)+'%';$('apy').textContent=apy.toFixed(1)+'%';$('days-label').textContent=days+'D';$('earnings').textContent='+$'+money(earnings);$('chart-end').textContent='DAY '+days;drawChart(amount,apy);}
function drawChart(amount,apy){var canvas=$('yield-chart'),ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height,pad=20,values=[];ctx.clearRect(0,0,w,h);for(var i=0;i<=40;i++)values.push(amount*(Math.pow(1+apy/100,days*i/40/365)-1));var max=Math.max(values[40]*1.2,1);ctx.strokeStyle='#1a3540';ctx.lineWidth=1;for(var k=1;k<=4;k++){var yy=pad+(h-2*pad)*k/4;ctx.beginPath();ctx.moveTo(pad,yy);ctx.lineTo(w-pad,yy);ctx.stroke();}var gradient=ctx.createLinearGradient(0,0,0,h);gradient.addColorStop(0,'rgba(0,240,245,.24)');gradient.addColorStop(1,'rgba(0,240,245,0)');ctx.beginPath();ctx.moveTo(pad,h-pad);for(var j=0;j<values.length;j++){var x=pad+(w-2*pad)*j/40,y=h-pad-values[j]/max*(h-2*pad);ctx.lineTo(x,y);}ctx.lineTo(w-pad,h-pad);ctx.closePath();ctx.fillStyle=gradient;ctx.fill();ctx.beginPath();for(var z=0;z<values.length;z++){var px=pad+(w-2*pad)*z/40,py=h-pad-values[z]/max*(h-2*pad);if(z===0)ctx.moveTo(px,py);else ctx.lineTo(px,py);}ctx.strokeStyle='#00f0f5';ctx.lineWidth=3;ctx.shadowColor='#00f0f5';ctx.shadowBlur=9;ctx.stroke();ctx.shadowBlur=0;ctx.beginPath();ctx.arc(w-pad,h-pad-values[40]/max*(h-2*pad),5,0,Math.PI*2);ctx.fillStyle='#baffff';ctx.fill();}
function renderPools(){var rows=pools.filter(function(p){return(filter==='all'||p.type===filter)&&p.pair.toLowerCase().indexOf(search)>=0;});$('pool-grid').innerHTML=rows.map(function(p){return '<article class="pool-card" data-pool="'+p.id+'"><div class="pool-title"><div class="coins '+p.kind+'"><span class="coin">'+p.icons[0]+'</span><span class="coin">'+p.icons[1]+'</span></div><div><h3>'+p.pair+'</h3><div class="pool-type">'+(p.type==='stable'?'STABLE PAIR':'VARIABLE PAIR')+' · DEMO</div></div><button class="star '+(favorites[p.id]?'active':'')+'" data-favorite="'+p.id+'" aria-label="Favorite '+p.pair+'" aria-pressed="'+Boolean(favorites[p.id])+'">'+(favorites[p.id]?'★':'☆')+'</button></div><div class="pool-apy"><strong>'+p.apy.toFixed(1)+'%</strong><span>SIMULATED APY</span></div><div class="pool-meta"><span>Total value locked</span><b>'+p.tvl+'</b></div><div class="pool-meta"><span>24h volume / fee</span><b>'+p.volume+' / '+p.fee+'</b></div><button class="outline" data-deposit="'+p.id+'">DEPOSIT ↗</button></article>';}).join('');$('pool-empty').hidden=rows.length!==0;}
function showModal(title,html){previousFocus=document.activeElement;$('modal-title').innerHTML=title;$('modal-content').innerHTML=html;$('modal').hidden=false;setTimeout(function(){var control=$('modal-content').querySelector('input,button');if(control)control.focus();},0);}
function closeModal(){$('modal').hidden=true;if(previousFocus&&previousFocus.focus)previousFocus.focus();}
function wallet(){if(connected){showModal('DEMO <span class="cyan">ACCOUNT</span>','<p>Demo balance: <b>'+money(balance,2)+' USDC</b></p><p class="modal-note">This account exists only in the example Lua program. No address, wallet extension, or private key is involved.</p><button class="outline full" id="disconnect">DISCONNECT DEMO ACCOUNT</button>');return;}showModal('CONNECT <span class="cyan">WALLET</span>','<p>Choose the sandbox account to test the interface.</p><button id="connect-demo" class="wallet-option"><span class="wallet-icon">◈</span><span><b>OCHD Demo Wallet</b><small>Virtual funds · '+(hasOC?'OC event + Lua receipt':'standalone browser preview')+'</small></span></button><p class="modal-note">Compatibility demo only. No real wallet connection or blockchain transaction is performed.</p>');}
function deposit(id){var pool=pools.filter(function(p){return p.id===id;})[0];if(!pool)return;if(!connected){wallet();return;}showModal('DEPOSIT <span class="cyan">'+pool.pair+'</span>','<p>Available: '+money(balance,2)+' demo USDC</p><div class="amount-field"><input id="deposit-amount" type="text" inputmode="decimal" value="100" aria-label="Demo deposit amount"><span>USDC</span></div><p class="modal-note">Simulated deposit. Lua validates the amount and returns a receipt. No real assets are transferred.</p><button id="confirm-deposit" data-pool-id="'+pool.id+'" class="gradient full">CONFIRM DEMO DEPOSIT ↗</button><div id="deposit-error" class="error" role="status"></div>');}
function action(button,name,args,onSuccess){button.disabled=true;emit(name,args).then(function(receipt){button.disabled=false;onSuccess();notify(receipt.message||'OC receipt received');}).catch(function(error){button.disabled=false;notify(error.message||String(error),true);});}
function docs(){showModal('INTERFACE <span class="cyan">LAB</span>','<p>This page tests CSS Grid/Flex, bundled variable fonts, text and box glow, gradients, sticky navigation, SVG, Canvas, sliders, search, filtering, clipboard input, dialogs, and OC round trips.</p><p>Calculator: earnings = deposit × ((1 + APY/100)^(days/365) − 1). All market metrics and APYs are fictional.</p><p class="modal-note">Lua publishes real OC uptime/memory alongside a virtual account balance. No machine control and no external network requests.</p><button id="modal-ping" class="outline full">TEST OC ROUND TRIP ↗</button>');}
document.addEventListener('click',function(event){var b=event.target.closest('button');if(!b)return;var scroll=b.getAttribute('data-scroll');if(scroll){$(scroll).scrollIntoView({behavior:'smooth',block:'start'});return;}if(b.hasAttribute('data-days')){days=Number(b.getAttribute('data-days'));Array.prototype.forEach.call($('periods').children,function(p){p.classList.toggle('selected',p===b);});calculate();return;}if(b.hasAttribute('data-filter')){filter=b.getAttribute('data-filter');Array.prototype.forEach.call($('filters').children,function(p){p.classList.toggle('selected',p===b);});renderPools();return;}if(b.hasAttribute('data-favorite')){var id=b.getAttribute('data-favorite');favorites[id]=!favorites[id];renderPools();return;}if(b.hasAttribute('data-deposit')){deposit(b.getAttribute('data-deposit'));return;}if(b.id==='connect-demo'){action(b,'demo_connect',{},function(){connected=true;syncWallet();closeModal();});return;}if(b.id==='disconnect'){action(b,'demo_disconnect',{},function(){connected=false;syncWallet();closeModal();});return;}if(b.id==='confirm-deposit'){var text=$('deposit-amount').value.replace(/,/g,'').trim(),n=Number(text);if(!text||!isFinite(n)||n<=0||n>balance||Math.abs(Math.round(n*100)-n*100)>0.00001){$('deposit-error').textContent='Enter a positive amount within the demo balance (up to 2 decimals).';return;}action(b,'demo_deposit',{pool:b.getAttribute('data-pool-id'),amount:n},function(){closeModal();});return;}if(b.id==='modal-ping')action(b,'echo_ping',{message:'NEON YIELD compatibility test'},function(){});});
$('amount').addEventListener('input',calculate);$('amount').addEventListener('blur',function(){var n=Number(this.value.replace(/,/g,''));if(isFinite(n)&&n>=0&&n<=1000000000)this.value=money(n);});$('rate').addEventListener('input',calculate);$('pool-search').addEventListener('input',function(){search=this.value.trim().toLowerCase();renderPools();});$('wallet-button').addEventListener('click',wallet);$('calculator-wallet').addEventListener('click',function(){if(connected)$('pools').scrollIntoView({behavior:'smooth'});else wallet();});$('docs-button').addEventListener('click',docs);$('token-details').addEventListener('click',function(){showModal('TOKEN <span class="cyan">DESIGN</span>','<p>The SVG ring shows a fictional allocation: 45% community, 25% treasury, 20% liquidity, 10% contributors.</p><p class="modal-note">This example does not issue, buy, or sell tokens. The chart is included to test SVG and glow rendering.</p>');});$('modal-close').addEventListener('click',closeModal);$('modal').addEventListener('click',function(e){if(e.target===$('modal'))closeModal();});document.addEventListener('keydown',function(e){if(e.key==='Escape'&&!$('modal').hidden){closeModal();e.preventDefault();}if(e.key==='Tab'&&!$('modal').hidden){var nodes=$('modal').querySelectorAll('button,input'),first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault();}}});$('ping-button').addEventListener('click',function(){action(this,'echo_ping',{message:'NEON YIELD compatibility test'},function(){});});
if(hasOC){$('oc-state').textContent='WAITING FOR OC';window.OC.onData(function(d){$('oc-state').textContent=d._online?'LIVE OC DATA':'OC OFFLINE';$('oc-dot').classList.toggle('online',Boolean(d._online));if(typeof d.uptime==='number')$('oc-uptime').textContent=Math.floor(d.uptime)+' SEC';if(typeof d.freeMemory==='number')$('oc-memory').textContent=money(d.freeMemory/1024,1)+' KiB';if(typeof d.balance==='number')balance=d.balance;if(typeof d.connected==='boolean')connected=d.connected;if(typeof d.receipts==='number')receipts=d.receipts;syncWallet();});}
renderPools();calculate();syncWallet();
})();
